import random
from typing import List


def generate_anagram(word: str) -> str:
    """Return a simple anagram generated by shuffling letters."""
    letters = list(word)
    random.shuffle(letters)
    return ''.join(letters)


def create_amalgamation(concept1: str, concept2: str) -> str:
    """Create a word by combining the first half of concept1 with the last half of concept2."""
    mid1 = len(concept1) // 2
    mid2 = len(concept2) // 2
    return concept1[:mid1] + concept2[mid2:]
